const ms = $json.measurements ?? [];
const backupSha256 = $json.backup_sha256;
if (!backupSha256 || !/^[0-9a-f]{64}$/.test(backupSha256)) throw new Error('Invalid backup_sha256 from parser');
return ms.map(x => {
  const w = Number(x.weight_kg);
  const fatPct = x.bodyfat_pct == null ? null : Number(x.bodyfat_pct);
  const waterPct = x.water_pct == null ? null : Number(x.water_pct);
  const musclePct = x.muscle_pct == null ? null : Number(x.muscle_pct);
  const dt = new Date(Number(x.timestamp_ms));
  return {json:{
    ...x,
    backup_sha256:backupSha256,
    measurement_key:`openscale_t9120:${x.measurement_id}:${x.timestamp_ms}`,
    source:'openscale_eufy_t9120',
    source_record_id:String(x.measurement_id),
    fat_mass_kg:fatPct == null ? null : w * fatPct / 100,
    hydration_kg:waterPct == null ? null : w * waterPct / 100,
    muscle_mass_kg:musclePct == null ? null : w * musclePct / 100,
    measured_at_iso:dt.toISOString(),
    local_date:dt.toLocaleDateString('en-CA',{timeZone:'Asia/Manila'}),
    comments:JSON.stringify({device:'Eufy T9120',transport:'openScale Android',bmi:x.bmi,visceral_fat:x.visceral_fat,impedance_ohm:x.impedance_ohm,backup_sha256:backupSha256})
  }};
});
